package com.bookstore.book.controller;
import com.bookstore.book.dto.BookRequest; import com.bookstore.book.entity.Book; import com.bookstore.book.service.BookService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/books") public class BookController { private final BookService service; public BookController(BookService service){this.service=service;} @GetMapping public List<Book> all(){return service.all();} @PostMapping public Book create(@Valid @RequestBody BookRequest r){return service.create(r);} @PutMapping("/{id}") public Book update(@PathVariable Long id,@Valid @RequestBody BookRequest r){return service.update(id,r);} @DeleteMapping("/{id}") public void delete(@PathVariable Long id){service.delete(id);} }
